import{_ as t,o as p,c as s,a5 as n}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"为ps脚本添加快捷键快速调用","日期":"2026-04-09T00:00:00.000Z","修改日期":"2026-04-09T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["Photoshop批处理"],"标签":["ps脚本","ps脚本快捷键","ps脚本添加快捷键调用"]},"headers":[{"level":3,"title":"步骤 1：将脚本保存到 Photoshop 的 Scripts 文件夹","slug":"步骤-1-将脚本保存到-photoshop-的-scripts-文件夹","link":"#步骤-1-将脚本保存到-photoshop-的-scripts-文件夹","children":[]},{"level":3,"title":"步骤 2：重启 Photoshop：","slug":"步骤-2-重启-photoshop","link":"#步骤-2-重启-photoshop","children":[]},{"level":3,"title":"步骤 3：创建一个动作来运行脚本","slug":"步骤-3-创建一个动作来运行脚本","link":"#步骤-3-创建一个动作来运行脚本","children":[]}],"relativePath":"md/Photoshop批处理/为ps脚本添加快捷键快速调用.md","filePath":"md/Photoshop批处理/为ps脚本添加快捷键快速调用.md"}'),a={name:"md/Photoshop批处理/为ps脚本添加快捷键快速调用.md"};function r(h,o,e,l,c,i){return p(),s("div",null,[...o[0]||(o[0]=[n('<h3 id="步骤-1-将脚本保存到-photoshop-的-scripts-文件夹" tabindex="-1">步骤 1：将脚本保存到 Photoshop 的 Scripts 文件夹 <a class="header-anchor" href="#步骤-1-将脚本保存到-photoshop-的-scripts-文件夹" aria-label="Permalink to &quot;步骤 1：将脚本保存到 Photoshop 的 Scripts 文件夹&quot;">​</a></h3><p>ps安装目录下的：安装目录\\Presets\\Scripts</p><p>如下图所示：<br><img src="https://www.softbangong.com/wp-content/uploads/2026/04/dOqYybLiCGreQw2.png" alt="null"></p><h3 id="步骤-2-重启-photoshop" tabindex="-1">步骤 2：重启 Photoshop： <a class="header-anchor" href="#步骤-2-重启-photoshop" aria-label="Permalink to &quot;步骤 2：重启 Photoshop：&quot;">​</a></h3><p>如果 Photoshop 正在运行，请关闭并重新启动，以确保新添加的脚本被识别。</p><h3 id="步骤-3-创建一个动作来运行脚本" tabindex="-1">步骤 3：创建一个动作来运行脚本 <a class="header-anchor" href="#步骤-3-创建一个动作来运行脚本" aria-label="Permalink to &quot;步骤 3：创建一个动作来运行脚本&quot;">​</a></h3><p>打开动作面板：<br> 在 Photoshop 中，导航到 窗口 &gt; 动作<br> 或按 Alt + F9（Windows）打开动作面板。</p><p>创建一个新的动作：<br> 在动作面板中，确保选中了您刚创建的动作集（如果有的话）。<br><img src="https://www.softbangong.com/wp-content/uploads/2026/04/dnOEhSXsbyFgVCN.png" alt="null"></p><p>点击动作面板底部的 创建新动作 按钮（通常是一个带加号的图标）。<br> 为动作命名、、分配快捷键、选择上边创建的组</p><p>如下图所示：【请注意，在操作时最好是先打开一个psd文件】<br><img src="https://www.softbangong.com/wp-content/uploads/2026/04/FcNpuXbwV8A7UiM.png" alt="null"></p><p>然后点击【记录】按钮</p><p>点击 记录 按钮。此时，Photoshop 会记录您在动作中的所有步骤。</p><p>选择ps左上角文件按钮依次找到<br> 文件 &gt; 脚本 &gt; [您的脚本名称]，例如 文件 &gt; 脚本 &gt; 【之前放进去的脚本】</p><p>如下图所示：点击脚本，会弹出程序，然后点击程序中的取消即可<br><img src="https://www.softbangong.com/wp-content/uploads/2026/04/nPy6boDhZKMrz72.png" alt="null"></p><p>然后点击停止按钮，如下图所示：<br><img src="https://www.softbangong.com/wp-content/uploads/2026/04/XgTJyw76sV4FjLH.png" alt="null"><br> ezinsert_paystart_1<br> 最后勾选如下图所示部分，即配置完成。使用快捷键就可以打开程序了<br><img src="https://www.softbangong.com/wp-content/uploads/2026/04/cplZPsUx7LI4qvg.png" alt="null"></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/538.html" target="_blank" rel="noreferrer">https://www.softbangong.com/538.html</a></p>',17)])])}const _=t(a,[["render",r]]);export{d as __pageData,_ as default};
